#!/usr/bin/env bash
# Generated by orca-setup from .orca-setup.json; change that file or the kit, not this one.
# One read-only snapshot of a running plan, for the architect's wait loop and for the user:
# the plan's task table, every agent in this repository's worktrees, terminals waiting at an
# approval prompt, failed worktree removals and
# recent Mac sleep. Usage: ./scripts/orca/orca-watch.sh [NNN-slug]   (default: the run updated last)
# Lines starting with "ATTENTION" need action; exit code 3 when any are printed.
set -uo pipefail
cd "$(dirname "$0")/../.." || exit 1
runs="/Users/serhii/Developer/emdash-images/.scratch/runs"
# The main checkout, also when the script runs from a plan worktree.
repo=$(cd "$(git rev-parse --path-format=absolute --git-common-dir)/.." && pwd)

# Default: the run whose status.md changed last.
# shellcheck disable=SC2012 # run folder names are plain slugs
latest=$(ls -t "$runs"/*/status.md 2>/dev/null | head -1)
run=${1:-}
[ -n "$run" ] || [ -z "$latest" ] || run=$(basename "$(dirname "$latest")")
attention=0

echo "== $(date '+%H:%M') plan ${run:-none}"
if [ -n "$run" ] && [ -f "$runs/$run/status.md" ]; then
  grep -E '^\| T[0-9]' "$runs/$run/status.md" | cut -c1-140
fi

echo "== agents"
agents=$(orca worktree ps --json 2>/dev/null | REPO="$repo" python3 -c '
import json, os, sys, time
repo = os.environ["REPO"]
data = json.load(sys.stdin).get("result", {})
for w in data.get("worktrees", []):
    if not w.get("path", "").startswith(repo):
        continue
    print("worktree", w.get("displayName"), "|", (w.get("comment") or "")[:100])
    if w.get("removalError"):
        print("ATTENTION removal failed:", w["removalError"][:160])
    for a in w.get("agents", []):
        if a.get("state") == "done":
            continue
        age = int(time.time() - a.get("updatedAt", 0) / 1000)
        print("  ", a.get("agentType"), a.get("state"), f"{age}s ago", "|", (a.get("toolInput") or "")[:90])
' || echo "ATTENTION orca is not reachable")
echo "$agents"
if grep -q '^ATTENTION' <<<"$agents"; then attention=1; fi

echo "== prompts"
handles=$(orca worktree list --json 2>/dev/null | REPO="$repo" python3 -c '
import json, os, sys
repo = os.environ["REPO"]
for w in json.load(sys.stdin).get("result", {}).get("worktrees", []):
    if w.get("path", "").startswith(repo):
        print(w["path"])
')
for path in $handles; do
  for t in $(orca terminal list --worktree "path:$path" --json 2>/dev/null | python3 -c '
import json, sys
for t in json.load(sys.stdin).get("result", {}).get("terminals", []):
    print(t["handle"])
'); do
    if orca terminal read --terminal "$t" --json 2>/dev/null | python3 -c '
import json, sys
tail = json.load(sys.stdin)["result"]["terminal"]["tail"][-16:]
sys.exit(0 if any("Do you want" in line for line in tail) else 1)
'; then
      echo "ATTENTION approval prompt in terminal $t ($(basename "$path"))"
      attention=1
    fi
  done
done

echo "== events (last 15 min)"
# Prompts shown to the user and hook refusals, from the roles' event log. Many refusals in a
# short time mean an agent is looping on a refused command instead of switching tools.
events=$(python3 - "$repo/.scratch/tmp/orca-events.jsonl" <<'PY'
import collections, json, sys, time
from datetime import datetime
try:
    lines = open(sys.argv[1]).read().splitlines()
except OSError:
    lines = []
since = time.time() - 900
recent = []
for line in lines:
    try:
        e = json.loads(line)
        if datetime.strptime(e["time"], "%Y-%m-%dT%H:%M:%S%z").timestamp() >= since and not e.get("probe"):
            recent.append(e)
    except (ValueError, KeyError):
        continue
refused = collections.Counter(e["role"] for e in recent if e["event"] == "refused")
for e in recent:
    if e["event"] == "prompt":
        print(f"prompt to the user: {e['role']} {e['tool']} {e['input'][:80]}")
for role, n in refused.items():
    last = [e for e in recent if e["event"] == "refused" and e["role"] == role][-1]
    if n >= 5:
        print(f"ATTENTION {role}: {n} hook refusals in 15 min, looping? last: {last['input'][:70]}")
    else:
        print(f"{role}: {n} hook refusals")
if not recent:
    print("none")
PY
)
echo "$events"
if grep -q '^ATTENTION' <<<"$events"; then attention=1; fi

echo "== sleep (last 2 today)"
pmset -g log 2>/dev/null | grep "^$(date '+%Y-%m-%d')" | grep -E $'\t(Sleep|Wake) ' | tail -2 | cut -c1-110

[ "$attention" -eq 0 ] || exit 3
